# CHALLENGE 2-7: Boost the red channel of each Almanac seal by 30 inside the loop.
def restore(pixels):
    result = []
    for r, g, b in pixels:
        pass
    return result

pixels = [[40, 20, 10], [20, 60, 120]]
colors = restore(pixels)
for index, color in enumerate(colors):
    hero.cast_color(color[0], color[1], color[2])
    if index < len(colors) - 1:
        hero.move_down(2)
        hero.move_right(3)

def transform(pixels):
    result = []
    for pixel in pixels:
        result.append([min(255, pixel[1] + 20), pixel[0], pixel[2]])
    return result

pixels = [[20,40,90],[80,140,30],[250,20,50]]
colors = transform(pixels)
for index, color in enumerate(colors):
    hero.cast_color(color[0], color[1], color[2])
    if index < 2:
        hero.move_down(3)
        hero.move_left(3)
        hero.move_up(3)

