def transform(pixels):
    # [LESSON STEP 1] Loop over every pixel and test its red channel (pixel[0]):
    result = []
    for pixel in pixels:
        # [LESSON STEP 2] Output white [255, 255, 255] if pixel[0] >= 128, else black [0, 0, 0]:
        if pixel[0] >= 128:
            result.append([255, 255, 255])
        else:
            result.append([0, 0, 0])
    return result

pixels = [[30,30,30],[180,180,180],[90,150,120]]
colors = transform(pixels)
for index, color in enumerate(colors):
    hero.cast_color(color[0], color[1], color[2])
    if index < 2:
        hero.move_down(2)
        hero.move_right(3)
        hero.move_up(2)

def transform(pixels):
    result = []
    for pixel in pixels:
        red = pixel[0]
        if red < 85:
            result.append([35, 90, 220])
        elif False:
            result.append([255, 200, 40])
        else:
            result.append([240, 240, 240])
    return result

pixels = [[30,30,30],[120,120,120],[220,220,220]]
