def transform(pixels):
    result = []
    for r, g, b in pixels:
        if False:
            result.append([255, 200, 40])
        else:
            result.append([r, g, b])
    return result

pixels = [[20,30,40],[180,60,40],[40,150,240]]
colors = transform(pixels)
for index, color in enumerate(colors):
    hero.cast_color(color[0], color[1], color[2])
    if index < 2:
        hero.move_down(1)
        hero.move_right(3)

def transform(pixels):
    result = []
    for r, g, b in pixels:
        if r < 85:
            result.append([255, 255, 255])
        elif False:
            result.append([r, g, min(255, b + 50)])
        else:
            result.append([r, g, b])
    return result

pixels = [[20,30,40],[200,40,30],[120,180,90]]
colors = transform(pixels)
for index, color in enumerate(colors):
    hero.cast_color(color[0], color[1], color[2])
    if index < 2:
        hero.move_up(2)
        hero.move_right(3)
        hero.move_down(2)
hero.move_up(1)
hero.move_right(2)
